import type { Question } from '../../lib/types'
export const storage_performance_questions: Question[] = [
  { id: 'd3-sto-001', domain: 3, topics: ['EFS', 'performance mode', 'latency'], type: 'single', stem: 'An EFS file system serves an HPC workload with thousands of concurrent connections. The team wants the lowest possible per-operation latency. Which performance mode minimizes latency?', options: [{ id: 'A', text: 'General Purpose mode' }, { id: 'B', text: 'Max I/O mode' }, { id: 'C', text: 'Bursting throughput mode' }, { id: 'D', text: 'Provisioned throughput mode' }], correct: ['A'], explanation: 'General Purpose performance mode has the lowest per-operation latency. Best for latency-sensitive workloads. Max I/O mode offers higher aggregate IOPS but sacrifices some per-operation latency — suitable when aggregate throughput matters more than individual operation speed.', distractors: { B: 'Max I/O provides higher aggregate throughput for parallel workloads but has slightly higher per-operation latency.', C: 'Bursting throughput mode controls throughput amount, not latency — performance mode selection affects latency.', D: 'Provisioned throughput controls throughput capacity, not per-operation latency — performance mode is the relevant setting.' } },
  { id: 'd3-sto-002', domain: 3, topics: ['EFS', 'elastic throughput', 'variable workloads'], type: 'single', stem: 'An EFS file system has highly unpredictable throughput needs — large spikes followed by hours of near-zero activity. Which throughput mode handles this automatically without over-provisioning?', options: [{ id: 'A', text: 'Bursting throughput' }, { id: 'B', text: 'Elastic throughput' }, { id: 'C', text: 'Provisioned throughput' }, { id: 'D', text: 'Max I/O mode' }], correct: ['B'], explanation: 'EFS Elastic Throughput (2022+) automatically scales throughput up and down based on actual workload requirements. No capacity planning needed. Charges based on GB transferred, making it cost-efficient for variable workloads.', distractors: { A: 'Bursting scales with file system size and uses credit accumulation — can still be constrained during prolonged high-throughput periods.', C: 'Provisioned throughput reserves capacity — pays for reserved amount even during the idle periods, which is wasteful.', D: 'Max I/O is a performance mode setting for latency vs. throughput tradeoff — not a throughput scaling mechanism.' } },
  { id: 'd3-sto-003', domain: 3, topics: ['S3', 'performance', 'prefix partitioning'], type: 'single', stem: 'An application uploads thousands of files per second to S3. All keys are prefixed with dates (e.g., 2026-07-27-file001). Is there a performance concern with date-based prefixes?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes' }, { id: 'D', text: 'Yes' }], correct: ['B'], explanation: 'Since July 2018, S3 supports 3,500 PUT/COPY/POST/DELETE and 5,500 GET/HEAD requests per second per prefix — and automatically scales to handle high request rates. The old advice about random prefixes to avoid hot partitions is outdated.', distractors: { A: 'Randomizing prefixes was the historical workaround before S3 auto-scaling — no longer necessary since 2018.', C: 'A single prefix concentrates all requests on one partition — using natural prefixes (dates) actually distributes load.', D: 'One upload per second is an extreme underutilization — S3 handles thousands of requests per prefix per second.' } },
  { id: 'd3-sto-004', domain: 3, topics: ['FSx', 'Lustre', 'HPC performance'], type: 'single', stem: 'An HPC simulation requires a shared parallel file system with sub-millisecond latency and hundreds of GB/s throughput for thousands of compute nodes. Which AWS storage service provides this?', options: [{ id: 'A', text: 'EFS with Max I/O performance mode' }, { id: 'B', text: 'Amazon FSx for Lustre' }, { id: 'C', text: 'S3 with high-bandwidth VPC endpoints' }, { id: 'D', text: 'EBS io2 Block Express' }], correct: ['B'], explanation: 'FSx for Lustre is the AWS implementation of the Lustre parallel file system. Provides sub-millisecond latency and throughput up to hundreds of GB/s. Integrates with S3 for data import/export. The standard for HPC, ML training, genomics.', distractors: { A: 'EFS Max I/O provides higher aggregate IOPS but not sub-millisecond latency or Lustre-level throughput for HPC workloads.', C: 'S3 is object storage — not a POSIX-compliant parallel file system with the performance characteristics needed for HPC.', D: 'EBS io2 Block Express is high-performance block storage for a single EC2 instance — cannot be shared across HPC cluster nodes.' } },
  { id: 'd3-sto-005', domain: 3, topics: ['S3', 'multipart upload', 'thresholds'], type: 'single', stem: 'At what file size does AWS recommend using S3 multipart upload for best performance?', options: [{ id: 'A', text: '5 MB' }, { id: 'B', text: '100 MB' }, { id: 'C', text: '5 GB' }, { id: 'D', text: '1 TB' }], correct: ['B'], explanation: 'AWS recommends multipart upload for files over 100 MB for improved parallelism and performance. It is REQUIRED for files over 5 GB (maximum single PUT size). Minimum part size is 5 MB (except the final part).', distractors: { A: '5 MB is the minimum part size in multipart upload — not the recommended threshold for when to use it.', C: '5 GB is the mandatory threshold where single PUT fails — multipart is recommended starting at 100 MB for performance.', D: 'Waiting until 1 TB to use multipart upload misses significant performance and reliability benefits starting at 100 MB.' } },
  { id: 'd3-sto-006', domain: 3, topics: ['FSx', 'Windows File Server', 'SMB'], type: 'single', stem: 'A Windows application requires a fully managed Windows file server with Active Directory integration and SMB protocol. Which AWS service provides this?', options: [{ id: 'A', text: 'Amazon EFS' }, { id: 'B', text: 'Amazon FSx for Windows File Server' }, { id: 'C', text: 'Amazon S3' }, { id: 'D', text: 'AWS Storage Gateway File Gateway' }], correct: ['B'], explanation: 'FSx for Windows File Server provides a fully managed native Windows file system: SMB protocol, NTFS, Active Directory integration, Windows ACLs, VSS (shadow copies), DFS Namespaces — a drop-in replacement for on-premises Windows file servers.', distractors: { A: 'EFS is NFS-based for Linux/POSIX workloads — not native Windows SMB.', C: 'S3 is object storage accessed via APIs — not a Windows-native SMB file server.', D: 'Storage Gateway File Gateway caches frequently accessed data locally and backs files to S3 — not a fully managed Windows file server with AD integration.' } },
  { id: 'd3-sto-007', domain: 3, topics: ['S3 Glacier', 'retrieval tiers', 'cost vs speed'], type: 'single', stem: 'A company runs nightly batch jobs using S3 Glacier Flexible Retrieval Bulk tier (cheapest). Occasionally urgent requests need data within minutes. How can both cost and speed requirements be met?', options: [{ id: 'A', text: 'Always use Expedited retrieval' }, { id: 'B', text: 'Use Bulk for scheduled nightly batch jobs; use Expedited for urgent ad-hoc requests' }, { id: 'C', text: 'Move all Glacier data to S3 Standard to eliminate retrieval delays' }, { id: 'D', text: 'Use S3 Glacier Instant Retrieval for all data' }], correct: ['B'], explanation: 'Glacier Flexible Retrieval allows choosing retrieval tier per request: Bulk (5-12 hours, cheapest) for predictable batch jobs; Expedited (1-5 minutes, most expensive) for urgent requests. Pay appropriately per use case.', distractors: { A: 'Expedited for all requests is expensive — batch jobs don\'t need 1-5 minute access and paying the premium unnecessarily increases cost.', C: 'S3 Standard costs 30x+ more than Glacier for infrequently accessed archival data — not cost-effective.', D: 'Glacier Instant Retrieval has a higher per-GB storage cost than Flexible Retrieval — appropriate for regular access, not bulk archival.' } },
  { id: 'd3-sto-008', domain: 3, topics: ['FSx', 'ONTAP', 'multi-protocol'], type: 'single', stem: 'Linux applications use NFS and Windows applications use SMB. Both need to access the same file data simultaneously. Which FSx offering natively supports both protocols on one file system?', options: [{ id: 'A', text: 'FSx for Windows File Server' }, { id: 'B', text: 'FSx for Lustre' }, { id: 'C', text: 'FSx for NetApp ONTAP' }, { id: 'D', text: 'Amazon EFS' }], correct: ['C'], explanation: 'FSx for NetApp ONTAP supports NFS (Linux), SMB (Windows), and iSCSI simultaneously on the same file system. Also supports data management features (snapshots, replication, tiering). Ideal for mixed-OS environments.', distractors: { A: 'FSx for Windows is SMB-only — Linux clients would need SMB client configuration and would not use native NFS.', B: 'FSx for Lustre is POSIX/HPC — no native SMB support for Windows applications.', D: 'EFS supports only NFS protocol — Windows applications cannot use native SMB with EFS.' } },
  { id: 'd3-sto-009', domain: 3, topics: ['EBS', 'gp3', 'baseline throughput'], type: 'single', stem: 'A 500 GB gp3 EBS volume is created without additional configuration. What is the default throughput provided?', options: [{ id: 'A', text: '250 MB/s' }, { id: 'B', text: '125 MB/s' }, { id: 'C', text: '1,000 MB/s' }, { id: 'D', text: 'Throughput scales proportionally with volume size, same as gp2 behavior' }], correct: ['B'], explanation: 'gp3 provides 125 MB/s baseline throughput for any volume size (configurable up to 1,000 MB/s independently). Unlike gp2 where throughput scales with size, gp3 baseline is fixed regardless of size.', distractors: { A: '250 MB/s is not the gp3 default — 125 MB/s is the baseline, which can be independently provisioned up to 1,000 MB/s.', C: '1,000 MB/s is the configurable maximum — not the default for any size.', D: 'gp3 throughput does NOT scale with size — this is gp2 behavior. gp3 has a fixed 125 MB/s baseline that can be independently configured.' } },
  { id: 'd3-sto-010', domain: 3, topics: ['S3', 'Transfer Acceleration', 'long-distance upload'], type: 'single', stem: 'Users in Australia upload 10 GB files to an S3 bucket in us-east-1 and experience slow speeds due to the long network path. What feature routes uploads through AWS edge infrastructure?', options: [{ id: 'A', text: 'S3 Multipart Upload alone' }, { id: 'B', text: 'S3 Transfer Acceleration' }, { id: 'C', text: 'CloudFront distribution for uploads' }, { id: 'D', text: 'AWS Direct Connect from Australia' }], correct: ['B'], explanation: 'S3 Transfer Acceleration routes uploads through the nearest CloudFront edge location and uses the AWS backbone for the long-haul path to S3. For users far from the bucket region, this can be 60-500% faster than direct S3 uploads over the internet.', distractors: { A: 'Multipart upload parallelizes parts but still uses the direct internet path — doesn\'t change the routing via edge locations.', C: 'CloudFront caches and distributes content downloads — it doesn\'t accelerate S3 uploads.', D: 'Direct Connect provides dedicated bandwidth but requires physical hardware installation and cannot be quickly deployed.' } },
  { id: 'd3-sto-011', domain: 3, topics: ['Storage Gateway', 'File Gateway', 'hybrid NFS'], type: 'single', stem: 'An on-premises application uses NFS to read and write files. The company wants files stored in S3 without changing the application. What enables transparent S3 storage via NFS?', options: [{ id: 'A', text: 'AWS DataSync' }, { id: 'B', text: 'AWS Storage Gateway File Gateway' }, { id: 'C', text: 'Amazon EFS' }, { id: 'D', text: 'AWS Transfer Family' }], correct: ['B'], explanation: 'Storage Gateway File Gateway runs on-premises (virtual appliance) and presents NFS/SMB shares. Files written are transparently stored as S3 objects. Applications see a normal file share — no code changes needed, no awareness of S3.', distractors: { A: 'DataSync is a one-time or scheduled bulk transfer tool — not a persistent NFS mount for ongoing application I/O.', C: 'EFS is cloud-native NFS — on-premises access requires VPN/Direct Connect and doesn\'t integrate transparently with S3.', D: 'Transfer Family provides SFTP/FTPS access to S3 — not NFS for on-premises applications.' } },
  { id: 'd3-sto-012', domain: 3, topics: ['Storage Gateway', 'cached volumes', 'limited local storage'], type: 'single', stem: 'An on-premises server has 50 TB of data but only 5 TB of local storage. Frequently accessed data should be local; the rest tiered to S3. Which Storage Gateway volume mode provides this?', options: [{ id: 'A', text: 'Volume Gateway stored volumes mode' }, { id: 'B', text: 'Volume Gateway cached volumes mode' }, { id: 'C', text: 'File Gateway' }, { id: 'D', text: 'Tape Gateway' }], correct: ['B'], explanation: 'Cached volumes mode stores all data in S3 and caches only frequently accessed data locally. The local cache can be much smaller than total data. Applications access iSCSI block volumes normally — no application changes needed.', distractors: { A: 'Stored volumes keeps all primary data on-premises — requires the same amount of local storage as total data, not solving the limited local storage problem.', C: 'File Gateway presents NFS/SMB file shares — different use case from block storage iSCSI volumes.', D: 'Tape Gateway is for backup applications using virtual tape library — not for general block storage tiering.' } },
  { id: 'd3-sto-013', domain: 3, topics: ['DataSync', 'migration', 'NFS to EFS'], type: 'single', stem: 'A company needs to migrate 100 TB from on-premises NFS to Amazon EFS within days while controlling bandwidth usage. What service handles this efficiently?', options: [{ id: 'A', text: 'AWS Storage Gateway' }, { id: 'B', text: 'AWS DataSync' }, { id: 'C', text: 'rsync over VPN' }, { id: 'D', text: 'AWS Snowball' }], correct: ['B'], explanation: 'DataSync uses parallel transfer protocols to move data 10x faster than traditional tools. Supports per-time-window bandwidth scheduling to avoid saturating production links. Integrates with EFS, S3, FSx, and on-premises NFS/SMB.', distractors: { A: 'Storage Gateway provides ongoing hybrid access — not a bulk migration tool for moving 100 TB efficiently.', C: 'rsync is single-threaded, slow for 100 TB, has no bandwidth scheduling — DataSync is optimized for this workload.', D: 'Snowball is for offline data transfer when network bandwidth is insufficient — DataSync is faster when adequate bandwidth exists.' } },
  { id: 'd3-sto-014', domain: 3, topics: ['S3', 'Intelligent-Tiering', 'unknown access patterns'], type: 'single', stem: 'An S3 bucket stores 500 TB with completely unknown access patterns — some objects may be hot, others cold. What storage class automatically optimizes cost without manual lifecycle management?', options: [{ id: 'A', text: 'S3 Standard for all objects' }, { id: 'B', text: 'S3 Intelligent-Tiering' }, { id: 'C', text: 'S3 Standard-IA for all objects' }, { id: 'D', text: 'S3 Glacier for all objects' }], correct: ['B'], explanation: 'S3 Intelligent-Tiering monitors access patterns and moves objects automatically between Frequent Access, Infrequent Access, Archive Instant Access, and Archive tiers. No manual lifecycle management needed — a small monthly monitoring fee per object applies.', distractors: { A: 'S3 Standard is expensive for rarely accessed data — no automatic cost optimization based on actual access patterns.', C: 'Standard-IA assumes all data is infrequently accessed — charges retrieval fees for unexpectedly hot objects.', D: 'Glacier requires restoration before access — not suitable for objects that might be accessed immediately.' } },
  { id: 'd3-sto-015', domain: 3, topics: ['EBS', 'io2', 'durability'], type: 'single', stem: 'A financial database requires the highest EBS volume durability available. Which volume type provides 99.999% (5 nines) durability compared to 99.8-99.9% for other types?', options: [{ id: 'A', text: 'gp3' }, { id: 'B', text: 'io2 and io2 Block Express' }, { id: 'C', text: 'st1' }, { id: 'D', text: 'All EBS types provide 99.999% durability' }], correct: ['B'], explanation: 'io2 volumes provide 99.999% durability (annual failure rate 0.001%) vs. 99.8-99.9% (AFR 0.1-0.2%) for gp3/gp2/io1/st1/sc1. Critical for financial databases and compliance workloads requiring highest storage reliability.', distractors: { A: 'gp3 provides 99.8-99.9% durability — lower than io2\'s 99.999%.', C: 'st1 HDD volumes provide 99.8-99.9% durability — lower than io2, not 99.999%.', D: 'EBS types have different durability specifications — io2 is specifically designed for highest durability requirements.' } },
  { id: 'd3-sto-016', domain: 3, topics: ['FSx', 'Lustre', 'S3 lazy loading'], type: 'single', stem: 'An ML training job reads training data from S3. The cluster uses FSx for Lustre. Does all S3 data need to be copied to FSx before training begins?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Use DataSync to copy S3 to FSx on a daily schedule for training job availability' }, { id: 'D', text: 'FSx for Lustre is incompatible with S3' }], correct: ['B'], explanation: 'FSx for Lustre integrates natively with S3. When linked to an S3 bucket, files appear in FSx immediately (metadata visible) but data is loaded on first access (lazy loading). After training, results sync back to S3. No full pre-copy required.', distractors: { A: 'The lazy loading / S3 native integration is specifically designed to eliminate the need for full pre-copy.', C: 'Daily DataSync is a manual external process — the native FSx-S3 integration provides on-demand loading automatically.', D: 'S3 integration is one of FSx for Lustre\'s key features — data doesn\'t need to be stored natively in Lustre.' } },
  { id: 'd3-sto-017', domain: 3, topics: ['S3', 'small files', 'request cost optimization'], type: 'single', stem: 'A company uploads 1 million small files (1 KB each) per hour to S3 individually, resulting in high S3 request fees. What optimization reduces per-request costs?', options: [{ id: 'A', text: 'Use S3 Multipart Upload for 1 KB files' }, { id: 'B', text: 'Combine small files into larger aggregate files before upload' }, { id: 'C', text: 'Switch to S3 Intelligent-Tiering for all files' }, { id: 'D', text: 'Request a higher S3 request limit from AWS Support to accommodate the volume' }], correct: ['B'], explanation: 'S3 charges $0.005 per 1,000 PUT requests. 1 million requests/hour = $5/hour in request fees. Packing small files into larger ones reduces the PUT count — fewer API calls means directly proportional cost reduction.', distractors: { A: 'Multipart upload is for files over 100 MB — using it on 1 KB files adds overhead and more API calls, increasing cost.', C: 'Storage class affects storage cost per GB — Intelligent-Tiering doesn\'t reduce per-PUT request fees.', D: 'Higher request limits don\'t reduce cost — you pay for each request regardless of volume limits.' } },
  { id: 'd3-sto-018', domain: 3, topics: ['EFS', 'Access Points', 'isolation'], type: 'single', stem: 'Multiple microservices share an EFS file system. Each should only see its own directory with its own POSIX user/group. What EFS feature provides this per-service isolation?', options: [{ id: 'A', text: 'Create separate EFS file systems per microservice' }, { id: 'B', text: 'EFS Access Points' }, { id: 'C', text: 'Configure POSIX file permissions on each service\'s directory for client-side enforcement' }, { id: 'D', text: 'Mount EFS with separate IAM execution roles per service' }], correct: ['B'], explanation: 'EFS Access Points create per-service entry points enforcing: a root directory (service only sees its directory), a POSIX user and group (enforces ownership). Multiple services share one EFS file system with isolation enforced server-side.', distractors: { A: 'Separate file systems per service is expensive and operationally complex — Access Points achieve isolation within one file system.', C: 'POSIX permissions are client-side and depend on correct user/group configuration on each client — Access Points enforce this server-side.', D: 'IAM roles control API access to the EFS API — Access Points enforce file system path and POSIX identity for data access.' } },
  { id: 'd3-sto-019', domain: 3, topics: ['S3', 'multipart copy', 'large objects'], type: 'single', stem: 'A company needs to copy a 100 GB S3 object within the same account to a different bucket. What feature enables efficient server-side copy?', options: [{ id: 'A', text: 'S3 CopyObject API' }, { id: 'B', text: 'S3 Multipart Upload with UploadPartCopy' }, { id: 'C', text: 'Download the object locally then upload to the destination bucket with a new key' }, { id: 'D', text: 'S3 Batch Operations' }], correct: ['B'], explanation: 'For objects over 5 GB, use S3 multipart copy (UploadPartCopy). This copies in parallel parts server-side — no data leaves AWS. Objects up to 5 GB can use the regular CopyObject API. 100 GB requires multipart.', distractors: { A: 'CopyObject API is limited to 5 GB objects — a 100 GB copy would fail with this method.', C: 'Downloading and re-uploading is inefficient — causes data egress charges and unnecessary bandwidth consumption.', D: 'S3 Batch Operations is for applying operations to thousands/millions of objects — not specifically for copying one large object efficiently.' } },
  { id: 'd3-sto-020', domain: 3, topics: ['FSx', 'OpenZFS', 'NFS with ZFS features'], type: 'single', stem: 'A development team needs a high-performance NFS file system with ZFS-native features (instant snapshots, clones, compression) and sub-millisecond latency. Which FSx offering provides this?', options: [{ id: 'A', text: 'FSx for Lustre' }, { id: 'B', text: 'FSx for OpenZFS' }, { id: 'C', text: 'FSx for Windows File Server' }, { id: 'D', text: 'Amazon EFS' }], correct: ['B'], explanation: 'FSx for OpenZFS provides ZFS-based file system: sub-millisecond latency, NFS support, instant ZFS snapshots (O(1) space), clones from snapshots, data compression, and up to 1 million IOPS. Suitable for dev/test, builds, and high-performance NFS.', distractors: { A: 'FSx for Lustre is a parallel HPC file system — not ZFS-based, no native snapshot/clone/compression features.', C: 'FSx for Windows is SMB/Windows-focused — VSS shadow copies are not the same as ZFS instant clones.', D: 'EFS is general-purpose NFS — no ZFS-native features like instant space-efficient clones or compression.' } },
  { id: 'd3-sto-021', domain: 3, topics: ['EBS', 'Elastic Volumes', 'live modification'], type: 'single', stem: 'An application using a gp2 EBS volume needs higher IOPS. Can the volume be changed to gp3 without stopping the EC2 instance?', options: [{ id: 'A', text: 'No' }, { id: 'B', text: 'Yes' }, { id: 'C', text: 'Only volume size can be increased live' }, { id: 'D', text: 'Only gp2 to gp3 is supported live' }], correct: ['B'], explanation: 'EBS Elastic Volumes allows changing volume type (gp2 to gp3, io1, io2, etc.), size, IOPS, and throughput while the volume is in use by a running instance. Changes apply during normal operation — no downtime needed.', distractors: { A: 'EBS modifications no longer require stopping the instance — Elastic Volumes enables live in-place modification.', C: 'All volume attributes (type, size, IOPS, throughput) can be changed live, not just size.', D: 'All volume type transitions are supported by Elastic Volumes — including changes to io1 and io2 types.' } },
  { id: 'd3-sto-022', domain: 3, topics: ['S3', 'Batch Operations', 'at-scale processing'], type: 'single', stem: 'A company needs to change the storage class of 10 billion existing S3 objects to Glacier. Running individual S3 API calls would take months. What processes this at scale?', options: [{ id: 'A', text: 'S3 Lifecycle rules' }, { id: 'B', text: 'S3 Batch Operations' }, { id: 'C', text: 'Lambda triggered by S3 events' }, { id: 'D', text: 'AWS CLI with --recursive flag' }], correct: ['B'], explanation: 'S3 Batch Operations runs actions (copy, restore, delete, change storage class, invoke Lambda, etc.) across billions of objects using an S3 Inventory report as the manifest. AWS manages execution, retries, and completion reporting.', distractors: { A: 'Lifecycle rules automate future transitions based on age — they do not immediately process billions of existing objects on demand.', C: 'Lambda with S3 events processes new uploads — not a bulk action mechanism for existing 10 billion objects.', D: 'AWS CLI iterates sequentially — no parallelism and would take far longer than Batch Operations for 10 billion objects.' } },
  { id: 'd3-sto-023', domain: 3, topics: ['EBS', 'Snapshot Archive', 'cost reduction'], type: 'single', stem: 'EBS snapshots older than 90 days are rarely needed but kept for compliance. Storage costs are high. What reduces snapshot storage cost while keeping them accessible?', options: [{ id: 'A', text: 'Delete old snapshots' }, { id: 'B', text: 'EBS Snapshot Archive tier' }, { id: 'C', text: 'Convert EBS snapshots to S3 Glacier directly' }, { id: 'D', text: 'EBS snapshots cannot be tiered' }], correct: ['B'], explanation: 'EBS Snapshot Archive tier stores snapshots at ~75% lower cost than standard snapshots. Restoring an archived snapshot takes 24-72 hours. Ideal for compliance snapshots that must be retained but are rarely accessed.', distractors: { A: 'Deleting snapshots violates the compliance retention requirement — archive tier preserves them at lower cost.', C: 'EBS snapshots are stored in S3 internally but managed entirely by AWS — you cannot directly export or manage them as S3 Glacier objects.', D: 'EBS Snapshot Archive is a real tiering feature — standard and archive tiers exist with different pricing.' } },
  { id: 'd3-sto-024', domain: 3, topics: ['S3', 'SSE-C', 'customer-managed keys'], type: 'single', stem: 'A company must manage their own encryption keys for S3 data. AWS must not be able to decrypt the data independently. Which SSE option meets this strict requirement?', options: [{ id: 'A', text: 'SSE-S3' }, { id: 'B', text: 'SSE-KMS' }, { id: 'C', text: 'SSE-C' }, { id: 'D', text: 'SSE-S3 with bucket policy' }], correct: ['C'], explanation: 'SSE-C: the customer includes the encryption key in each S3 API request. AWS uses the key to encrypt/decrypt but never stores it. AWS cannot decrypt data without the customer providing the key — meets the "AWS must not be able to decrypt" requirement.', distractors: { A: 'SSE-S3 uses AWS-managed keys — AWS can decrypt at any time, violating the requirement.', B: 'SSE-KMS uses KMS where AWS has access to the key material and can decrypt through authorized KMS operations.', D: 'SSE-S3 with bucket policy still uses AWS-managed keys — AWS retains decryption capability regardless of access policies.' } },
  { id: 'd3-sto-025', domain: 3, topics: ['Storage Gateway', 'Tape Gateway', 'VTL'], type: 'single', stem: 'A company uses physical tape libraries for backups with Veeam backup software. They want to eliminate physical tapes while keeping the same backup software. What AWS service enables this?', options: [{ id: 'A', text: 'AWS Backup with Glacier Deep Archive' }, { id: 'B', text: 'AWS Storage Gateway Tape Gateway' }, { id: 'C', text: 'AWS DataSync' }, { id: 'D', text: 'S3 with Veeam S3-compatible backup target' }], correct: ['B'], explanation: 'Tape Gateway presents a VTL interface — iSCSI virtual tapes compatible with all major backup software including Veeam and Commvault. Virtual tapes are stored in S3 and can be archived to S3 Glacier Deep Archive. No backup software changes needed.', distractors: { A: 'AWS Backup is an AWS-native service and doesn\'t present a VTL interface to legacy backup software like Veeam.', C: 'DataSync is a data transfer and migration tool — not a VTL replacement for backup software workflows.', D: 'Direct S3 integration requires backup software version that supports S3 — Tape Gateway works with existing VTL-compatible versions without upgrade.' } },
  { id: 'd3-sto-026', domain: 3, topics: ['EBS', 'size limits'], type: 'single', stem: 'What is the maximum size of a single EBS volume for gp3 and io2 types?', options: [{ id: 'A', text: '1 TB' }, { id: 'B', text: '16 TiB' }, { id: 'C', text: '64 TiB' }, { id: 'D', text: '1 PB' }], correct: ['C'], explanation: 'The maximum EBS volume size is 64 TiB for SSD types (gp3, gp2, io1, io2, io2 Block Express). st1 and sc1 HDD types support up to 16 TiB. For data exceeding 64 TiB, use RAID 0 across multiple volumes.', distractors: { A: '1 TB was an early limit — modern EBS supports up to 64 TiB per volume for SSD types.', B: '16 TiB is the maximum for st1/sc1 HDD types — SSD types (gp3, io2) support up to 64 TiB.', D: 'Single EBS volume maximum is 64 TiB — not petabyte scale. Use multiple volumes and RAID or a different architecture for larger datasets.' } },
  { id: 'd3-sto-027', domain: 3, topics: ['S3', 'versioning', 'NoncurrentVersionExpiration'], type: 'single', stem: 'S3 versioning is enabled on a bucket. Old noncurrent versions are accumulating and increasing storage costs. What lifecycle action removes old versions automatically?', options: [{ id: 'A', text: 'NoncurrentVersionExpiration lifecycle action' }, { id: 'B', text: 'S3 Intelligent-Tiering automatically removes noncurrent versions after a configurable retention period' }, { id: 'C', text: 'Disabling versioning on the bucket removes all existing noncurrent versions' }, { id: 'D', text: 'S3 Object Lock automatically removes versions when the retention period expires' }], correct: ['A'], explanation: 'NoncurrentVersionExpiration lifecycle rule permanently deletes noncurrent object versions after the configured number of days since they became noncurrent. Use NewerNoncurrentVersions to keep the most recent N versions.', distractors: { B: 'Intelligent-Tiering moves objects between access tiers — it does not delete noncurrent versions.', C: 'Disabling versioning stops creating new versions (suspends versioning) — it does not delete existing noncurrent versions.', D: 'Object Lock prevents deletion during a retention period — it is the opposite of automatic version removal.' } },
  { id: 'd3-sto-028', domain: 3, topics: ['EFS', 'lifecycle management', 'EFS-IA'], type: 'single', stem: 'An EFS file system stores files that are rarely accessed after 14 days. The team wants to reduce storage costs for these files automatically. What EFS feature provides this?', options: [{ id: 'A', text: 'EFS Standard storage class' }, { id: 'B', text: 'EFS lifecycle management' }, { id: 'C', text: 'Migrate infrequently accessed files to S3 Standard-IA using a scheduled Lambda function' }, { id: 'D', text: 'Compress infrequently accessed files' }], correct: ['B'], explanation: 'EFS Lifecycle Management automatically moves files to EFS-IA based on access patterns (configurable: 7, 14, 30, 60, 90 days). EFS-IA is up to 92% cheaper than EFS Standard. Files automatically move back to Standard on next access.', distractors: { A: 'EFS Standard is the most expensive tier — EFS-IA provides significant savings for infrequently accessed files.', C: 'Moving to S3 requires application changes and loses NFS access semantics — EFS lifecycle is transparent to applications.', D: 'EFS charges for actual bytes stored — compression reduces apparent size but EFS lifecycle tiering is the cost optimization solution.' } },
  { id: 'd3-sto-029', domain: 3, topics: ['S3 Glacier', 'restore', 'temporary copy'], type: 'single', stem: 'After restoring a file from S3 Glacier to S3, the company notices they are charged for both Glacier storage and S3 Standard. Why?', options: [{ id: 'A', text: 'Glacier Expedited retrieval permanently moves data to S3 Standard and deletes the Glacier copy' }, { id: 'B', text: 'Glacier restore creates a temporary S3 Standard copy while the original remains in Glacier' }, { id: 'C', text: 'The restore operation moved data to S3 Standard permanently' }, { id: 'D', text: 'This is a billing error' }], correct: ['B'], explanation: 'Glacier restore creates a temporary copy in S3 Standard (or Reduced Redundancy). The original object remains in Glacier. The temporary copy has a configurable TTL (1-365 days). After TTL, the S3 copy is deleted — only Glacier retains the data.', distractors: { A: 'Expedited retrieval creates a temporary copy — it does NOT permanently move or delete the Glacier original.', C: 'The restore creates a temporary copy — the 90-day minimum storage charge is for Glacier Flexible Retrieval, separate from the temporary restore copy.', D: 'Dual charging is expected behavior during the restore window — both storage charges are legitimate until the restore TTL expires.' } },
  { id: 'd3-sto-030', domain: 3, topics: ['EBS', 'RAID 0', 'IOPS scaling'], type: 'single', stem: 'A database requires more IOPS than a single EBS io2 volume can provide at a reasonable size. How can IOPS be increased beyond a single volume\'s limit?', options: [{ id: 'A', text: 'Increase the EBS volume size' }, { id: 'B', text: 'Configure RAID 0 (striping) across multiple EBS volumes' }, { id: 'C', text: 'Use RAID 1 (mirroring)' }, { id: 'D', text: 'Attach multiple EBS volumes independently' }], correct: ['B'], explanation: 'RAID 0 stripes data across multiple EBS volumes, combining their IOPS. 4 × 64,000 IOPS volumes = ~256,000 aggregate IOPS. Note: RAID 0 has no fault tolerance — a single volume failure loses all data.', distractors: { A: 'io2 IOPS are independently provisioned, not determined by size — increasing size alone doesn\'t add IOPS.', C: 'RAID 1 mirrors data for redundancy — halves effective write IOPS and only marginally improves read throughput.', D: 'Multiple independent volumes require the application/OS to explicitly distribute I/O — RAID 0 provides transparent striping.' } },
  { id: 'd3-sto-031', domain: 3, topics: ['S3', 'Object Lock', 'WORM compliance'], type: 'single', stem: 'An S3 bucket stores compliance data that must be protected against deletion by anyone — including the root account. Which configuration provides the strongest protection?', options: [{ id: 'A', text: 'S3 Object Lock in Compliance mode + Versioning' }, { id: 'B', text: 'Bucket policy with explicit Deny + MFA Delete + Versioning' }, { id: 'C', text: 'S3 Block Public Access only' }, { id: 'D', text: 'S3 Lifecycle rules with no expiration configured' }], correct: ['A'], explanation: 'S3 Object Lock Compliance mode + Versioning: objects cannot be deleted or modified by anyone, including the AWS root account, during the retention period. This is true WORM compliance — the strongest available protection.', distractors: { B: 'Policy deny + MFA Delete is strong but the root account can still modify or remove bucket policies — Compliance mode Object Lock cannot be bypassed by root.', C: 'Block Public Access prevents public access — it does not prevent deletion by authorized account principals.', D: 'Lifecycle rules without expiration allow continued storage — they are management rules, not deletion protection.' } },
  { id: 'd3-sto-032', domain: 3, topics: ['Storage Gateway', 'stored volumes', 'DR use case'], type: 'single', stem: 'A company uses Storage Gateway Volume Gateway in stored mode for on-premises data. How can this be leveraged for cloud-based disaster recovery?', options: [{ id: 'A', text: 'Stored volumes are only accessible on-premises' }, { id: 'B', text: 'EBS snapshots of stored volumes are created in AWS' }, { id: 'C', text: 'Volume Gateway stored mode is only for backup tapes' }, { id: 'D', text: 'Manually export volume data to S3 and restore using DataSync during a DR event' }], correct: ['B'], explanation: 'Storage Gateway stored volumes asynchronously snapshot to AWS as EBS snapshots. During DR, restore the latest EBS snapshot to a new EBS volume, attach to an EC2 instance, and access the data — cloud-based recovery from on-premises storage.', distractors: { A: 'Stored volumes create EBS snapshots in AWS — DR recovery using those snapshots is a core use case.', C: 'Volume Gateway stored mode uses EBS snapshots for DR — Tape Gateway is the virtual tape library product.', D: 'Manual S3 export is unnecessary — EBS snapshots are automatically created and ready for EC2 restoration.' } },
  { id: 'd3-sto-033', domain: 3, topics: ['S3', 'strong consistency', 'list operations'], type: 'single', stem: 'An application writes objects to S3 and immediately lists the bucket to verify they were written. Will the list always include the newly written objects?', options: [{ id: 'A', text: 'No' }, { id: 'B', text: 'Yes' }, { id: 'C', text: 'Only if S3 versioning is enabled' }, { id: 'D', text: 'Yes for new objects, but no for overwrite updates' }], correct: ['B'], explanation: 'S3 strong read-after-write consistency (December 2020) covers all operations: GET, PUT, DELETE, and LIST. Listing a bucket immediately after writing will reflect the newly written objects — no delay or eventual consistency concerns.', distractors: { A: 'This was true before December 2020 — S3 list operations are now strongly consistent for all objects.', C: 'Strong consistency applies regardless of versioning configuration — it is not conditional on versioning being enabled.', D: 'All S3 operations including overwrites and deletes are strongly consistent since December 2020.' } },
  { id: 'd3-sto-034', domain: 3, topics: ['EBS', 'default encryption', 'account-level'], type: 'single', stem: 'A new AWS account needs to ensure all EBS volumes created in a region are encrypted by default, even if developers forget to check the encryption box. What setting achieves this?', options: [{ id: 'A', text: 'Create a CloudWatch alarm to detect and alert on unencrypted EBS volumes after creation' }, { id: 'B', text: 'Enable EBS encryption by default at the account/region level' }, { id: 'C', text: 'Use AWS Config managed rule encrypted-volumes to detect and auto-remediate unencrypted volumes' }, { id: 'D', text: 'Apply an IAM policy denying ec2:CreateVolume unless the encrypted parameter is true' }], correct: ['B'], explanation: 'EBS default encryption can be enabled per account per region in EC2 settings. When enabled, all new EBS volumes are automatically encrypted using the default KMS key (or a specified CMK). Existing volumes are not retroactively encrypted.', distractors: { A: 'CloudWatch alarms detect volumes after creation — they alert but don\'t prevent unencrypted volume creation.', C: 'AWS Config detects non-compliant volumes and can auto-remediate — EBS default encryption prevents creation upfront.', D: 'IAM policy denial adds friction for all CreateVolume calls — EBS default encryption silently encrypts without blocking the operation.' } },
  { id: 'd3-sto-035', domain: 3, topics: ['EFS', 'IAM authorization', 'NFS access'], type: 'single', stem: 'An EFS file system should only be mountable by EC2 instances with a specific IAM role. How is this IAM-based mount authorization enforced?', options: [{ id: 'A', text: 'POSIX file permissions on the file system' }, { id: 'B', text: 'EFS resource policy granting elasticfilesystem:ClientMount to the specific IAM role' }, { id: 'C', text: 'Security groups on the EFS mount target' }, { id: 'D', text: 'EFS does not support IAM-based access control' }], correct: ['B'], explanation: 'EFS supports IAM authorization for NFS clients. Configure an EFS resource-based policy allowing elasticfilesystem:ClientMount from specific IAM roles. The EC2 instance\'s IAM role must be authorized — unauthorized roles cannot mount the file system.', distractors: { A: 'POSIX permissions control file access within an already-mounted file system — not whether a client can mount it in the first place.', C: 'Security groups control NFS network access (port 2049) by network identity — not by IAM role identity.', D: 'EFS IAM authorization for NFS clients has been supported since 2020 — it is a real and commonly tested feature.' } },
  { id: 'd3-sto-036', domain: 3, topics: ['S3', 'tag-based lifecycle', 'Glacier'], type: 'single', stem: 'Files tagged with archive=true in S3 should be moved to Glacier after 30 days. How is this tag-based transition implemented?', options: [{ id: 'A', text: 'S3 Lifecycle rules do not support tag-based filtering' }, { id: 'B', text: 'Create an S3 Lifecycle rule with tag filter archive=true and Glacier transition after 30 days' }, { id: 'C', text: 'Deploy a Lambda function triggered by S3 events to check tags and move objects to Glacier' }, { id: 'D', text: 'Use S3 Batch Operations with a daily scheduled job to find tagged objects and change storage class' }], correct: ['B'], explanation: 'S3 Lifecycle rules support tag-based filtering alongside prefix filtering. Configure a rule with filter tag archive=true and a transition action to Glacier after 30 days from object creation.', distractors: { A: 'S3 Lifecycle rules support both prefix and object tag filtering — tag-based filtering is a fully supported feature.', C: 'Lambda-based lifecycle requires code, permissions, and operational overhead — Lifecycle rules handle this natively.', D: 'Batch Operations is for one-time bulk actions — Lifecycle rules handle ongoing automated tag-based transitions.' } },
  { id: 'd3-sto-037', domain: 3, topics: ['DataSync', 'S3 to S3', 'checksum verification'], type: 'single', stem: 'A company needs to copy 50 TB of S3 data from one region to another with per-file checksum verification to ensure data integrity. What service provides both speed and validation?', options: [{ id: 'A', text: 'AWS CLI s3 sync command' }, { id: 'B', text: 'AWS DataSync' }, { id: 'C', text: 'S3 Cross-Region Replication' }, { id: 'D', text: 'S3 Batch Operations CopyObject' }], correct: ['B'], explanation: 'DataSync supports S3-to-S3 transfers with parallel processing, configurable bandwidth controls, and built-in data integrity verification (checksums). For a one-time 50 TB migration with validation requirements, DataSync is the appropriate service.', distractors: { A: 'CLI s3 sync is single-threaded without parallelism by default, has no bandwidth control, and doesn\'t provide per-file integrity reporting.', C: 'CRR is for ongoing continuous replication — not appropriate for a one-time migration with integrity verification.', D: 'Batch Operations CopyObject is fast for mass operations but doesn\'t provide per-file checksum verification in the transfer.' } },
  { id: 'd3-sto-038', domain: 3, topics: ['EBS', 'direct APIs', 'snapshot access'], type: 'single', stem: 'A backup application needs to read changed blocks from EBS snapshots programmatically without creating a volume or attaching it to an instance. What APIs enable this?', options: [{ id: 'A', text: 'EBS snapshots must be mounted on an EC2 instance before block-level data can be read' }, { id: 'B', text: 'Amazon EBS direct APIs (ListSnapshotBlocks, GetSnapshotBlock, ListChangedBlocks)' }, { id: 'C', text: 'AWS DataSync with EBS snapshot source' }, { id: 'D', text: 'Amazon S3 Glacier Restore API' }], correct: ['B'], explanation: 'EBS direct APIs: ListSnapshotBlocks (list all blocks in a snapshot), ListChangedBlocks (changed blocks between two snapshots), GetSnapshotBlock (read specific block data). No volume creation needed — ideal for backup and incremental backup software.', distractors: { A: 'EBS direct APIs specifically eliminate the need to create a volume — directly accessing block data from snapshots is the purpose.', C: 'DataSync is a file/object transfer service — not a block-level EBS snapshot API.', D: 'Glacier Restore API retrieves archived objects from S3 Glacier — not EBS block-level snapshot access.' } },
  { id: 'd3-sto-039', domain: 3, topics: ['S3', 'multipart upload', 'TCP parallelism'], type: 'single', stem: 'A company transfers large files to S3 using a single TCP connection and throughput is limited. What optimization maximizes upload throughput?', options: [{ id: 'A', text: 'A single optimized TCP connection provides the best S3 upload performance available' }, { id: 'B', text: 'S3 multipart upload with parallel parts' }, { id: 'C', text: 'Increase TCP receive window size on the client OS for better S3 throughput' }, { id: 'D', text: 'Use UDP-based file transfer protocol instead of TCP for S3 uploads' }], correct: ['B'], explanation: 'Single TCP connection throughput is limited by round-trip latency and TCP window size. Multipart upload parallelizes parts across multiple HTTP connections — each part uses a separate TCP connection, effectively multiplying available bandwidth usage.', distractors: { A: 'Single TCP connection is a throughput bottleneck — parallelism is necessary for maximizing large file upload speeds.', C: 'TCP window tuning helps somewhat but is complex — multipart parallel upload is the AWS-recommended approach.', D: 'S3 uses HTTP/HTTPS over TCP — UDP-based protocols are not supported for S3 uploads.' } },
  { id: 'd3-sto-040', domain: 3, topics: ['FSx', 'Lustre', 'scratch vs persistent'], type: 'single', stem: 'An HPC job runs for 2 hours, reads data from S3, processes it, and exports results back to S3. The file system is not needed between jobs. Which FSx for Lustre deployment type minimizes cost?', options: [{ id: 'A', text: 'Persistent deployment' }, { id: 'B', text: 'Scratch deployment' }, { id: 'C', text: 'Provisioned IOPS deployment' }, { id: 'D', text: 'On-Demand deployment' }], correct: ['B'], explanation: 'FSx for Lustre Scratch deployment is for temporary short-term workloads: no data redundancy, highest burst performance, lowest per-GB-hour cost. Ideal for HPC jobs where data comes from S3 and results export back — scratch data is not needed to persist.', distractors: { A: 'Persistent deployment maintains data durably across infrastructure reboots — more expensive and unnecessary for temporary HPC jobs.', C: 'There is no "Provisioned IOPS" FSx for Lustre deployment type — scratch and persistent are the two options.', D: 'There is no "On-Demand" FSx for Lustre deployment type — pricing is based on the provisioned storage capacity.' } },
  { id: 'd3-sto-041', domain: 3, topics: ['S3', 'lifecycle expiration', 'log retention'], type: 'single', stem: 'A log S3 bucket accumulates files indefinitely. Logs older than 90 days are no longer needed. What lifecycle action removes them automatically?', options: [{ id: 'A', text: 'S3 Intelligent-Tiering with 90-day archive configuration' }, { id: 'B', text: 'S3 Lifecycle Expiration rule' }, { id: 'C', text: 'S3 Object Lock with 90-day retention' }, { id: 'D', text: 'Configure an S3 bucket storage limit of 90 days' }], correct: ['B'], explanation: 'S3 Lifecycle Expiration rules permanently delete objects after a configured number of days from creation. For versioned buckets, also configure NoncurrentVersionExpiration and expired-object-delete-marker rules for complete cleanup.', distractors: { A: 'Intelligent-Tiering manages storage class transitions — not automatic deletion based on object age.', C: 'Object Lock prevents deletion during the retention period — the opposite of automatic deletion after 90 days.', D: 'S3 has no configurable maximum bucket storage limit — objects must be managed explicitly via Lifecycle rules.' } },
  { id: 'd3-sto-042', domain: 3, topics: ['EBS', 'Fast Snapshot Restore', 'warm-up'], type: 'single', stem: 'EC2 instances launched from EBS snapshots are slow for the first few minutes because blocks are loaded lazily from S3. What eliminates this warm-up period?', options: [{ id: 'A', text: 'Pre-warm volumes manually by reading all blocks (dd command) immediately after each instance launch' }, { id: 'B', text: 'Enable EBS Fast Snapshot Restore (FSR)' }, { id: 'C', text: 'Use instance store volumes instead of EBS' }, { id: 'D', text: 'Choose a larger EBS volume size' }], correct: ['B'], explanation: 'Fast Snapshot Restore pre-warms blocks in specific AZs so volumes restored from FSR-enabled snapshots are immediately at full IOPS — no lazy initialization phase. Especially valuable for frequently used golden AMIs and DR testing.', distractors: { A: 'Manual pre-warming with dd works but adds time after every launch — FSR eliminates the need by pre-initializing proactively.', C: 'Instance store doesn\'t persist data and cannot be restored from a snapshot — not a substitute for EBS.', D: 'Larger gp2 volumes have higher IOPS allocation but all EBS types still lazy-load from S3 — FSR is the solution.' } },
  { id: 'd3-sto-043', domain: 3, topics: ['S3', 'versioning', 'delete markers', 'cleanup'], type: 'single', stem: 'A versioned S3 bucket has accumulated many delete markers for objects that have no remaining noncurrent versions. These empty delete markers waste storage. What lifecycle action cleans them up?', options: [{ id: 'A', text: 'NoncurrentVersionExpiration' }, { id: 'B', text: 'Expiration action with expired-object-delete-marker=true' }, { id: 'C', text: 'AbortIncompleteMultipartUpload' }, { id: 'D', text: 'StorageClassTransition to Glacier' }], correct: ['B'], explanation: 'The lifecycle Expiration action with expired-object-delete-marker enabled automatically removes delete markers that have no remaining noncurrent versions for that object key. Cleans up the accumulated markers from versioned deletion operations.', distractors: { A: 'NoncurrentVersionExpiration deletes noncurrent object versions — not the delete markers themselves.', C: 'AbortIncompleteMultipartUpload cleans up abandoned multipart upload parts — unrelated to delete marker cleanup.', D: 'Delete markers are metadata objects — they cannot be transitioned to storage classes like Glacier.' } },
  { id: 'd3-sto-044', domain: 3, topics: ['Transfer Family', 'SFTP', 'S3 integration'], type: 'single', stem: 'Business partners send files via SFTP to a company. The company wants to store all received files in S3 without changing the partners\' SFTP workflow. What managed service bridges SFTP and S3?', options: [{ id: 'A', text: 'EC2 instance running OpenSSH/SFTP server' }, { id: 'B', text: 'AWS Transfer Family for SFTP' }, { id: 'C', text: 'S3 has no native SFTP support' }, { id: 'D', text: 'AWS DataSync with SFTP source' }], correct: ['B'], explanation: 'AWS Transfer Family provides managed SFTP (also FTPS, FTP, AS2) endpoints. Partners upload via standard SFTP — files are stored directly in S3 or EFS. Supports custom domains, identity providers (AD, LDAP, Cognito), and no server management.', distractors: { A: 'EC2 SFTP requires OS patching, HA configuration, key management, and DataSync for S3 sync — Transfer Family is fully managed.', C: 'AWS SDK upload is a valid alternative but requires partners to change their tooling — Transfer Family preserves existing SFTP workflows.', D: 'DataSync is a bulk migration/replication tool — not an ongoing SFTP endpoint for partners to upload files to.' } },
  { id: 'd3-sto-045', domain: 3, topics: ['S3', 'VPC Gateway Endpoint', 'private access'], type: 'single', stem: 'EC2 instances in private subnets need to access S3 without internet traffic or NAT Gateway charges. What provides free, private S3 access from within a VPC?', options: [{ id: 'A', text: 'Internet Gateway' }, { id: 'B', text: 'S3 Interface Endpoint (PrivateLink)' }, { id: 'C', text: 'S3 Gateway Endpoint' }, { id: 'D', text: 'NAT Gateway with S3 IP routes' }], correct: ['C'], explanation: 'S3 Gateway Endpoints are free and provide VPC instances private access to S3 without NAT Gateways or internet. Traffic stays on the AWS network. Configure a route in the VPC route table pointing S3 prefixes to the gateway endpoint.', distractors: { A: 'Internet Gateway requires a public IP or NAT Gateway — private subnet instances cannot use IGW directly.', B: 'S3 Interface Endpoints exist but have an hourly charge per AZ — Gateway endpoints are free and preferred.', D: 'NAT Gateway has $0.045/hour and $0.045/GB data processing charges — S3 Gateway Endpoint eliminates this cost.' } },
]
